        Dhikr(text: 'أَعُوذُ بِاللَّهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ. بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ.', count: 1, description: 'دعاء دخول المسجد'),
        Dhikr(text: 'بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ، اللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ.', count: 1, description: 'دعاء الخروج من المسجد'),
        Dhikr(text: 'اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ.', count: 1, description: 'دعاء ما بعد الأذان'),
        Dhikr(text: 'سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَهَ غَيْرُكَ.', count: 1, description: 'دعاء الاستفتاح في الصلاة'),
      ],
    ),
    DhikrCategory(
      id: 'ruqyah',
      title: 'الرقية الشرعية',
      icon: 'quran',
      adhkar: [
        Dhikr(text: 'بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ * الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ * الرَّحْمَنِ الرَّحِيمِ * مَالِكِ يَوْمِ الدِّينِ * إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ * اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ * صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ', count: 7, reference: 'سورة الفاتحة', description: 'فضلها: أعظم سورة في القرآن، وهي الشافية والكافية والواقية بإذن الله.'),
        Dhikr(text: 'الم * ذَلِكَ الْكِتَابُ لاَ رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ * الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلاةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ * والَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَبِالآخِرَةِ هُمْ يُوقِنُونَ * أُوْلَـئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُوْلَـئِكَ هُمُ الْمُفْلِحُونَ', count: 1, reference: 'سورة البقرة (الآيات 1-5)', description: 'فضلها: الهداية والحفظ من الشياطين، وسورة البقرة لا تستطيعها البطلة (أي السحرة).'),
        Dhikr(text: 'وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لاَّ إِلَهَ إِلاَّ هُوَ الرَّحْمَنُ الرَّحِيمُ * إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالأَرْضِ وَاخْتِلاَفِ اللَّيْلِ وَالنَّهَارِ وَالْفُلْكِ الَّتِي تَجْرِي فِي الْبَحْرِ بِمَا يَنفَعُ النَّاسَ وَمَا أَنزَلَ اللّهُ مِنَ السَّمَاء مِن مَّاء فَأَحْيَا بِهِ الأرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ وَتَصْرِيفِ الرِّيَاحِ وَالسَّحَابِ الْمُسَخِّرِ بَيْنَ السَّمَاء وَالأَرْضِ لآيَاتٍ لِّقَوْمٍ يَعْقِلُونَ', count: 1, reference: 'سورة البقرة (الآيات 163-165)', description: 'فضلها: التذكير بوحدانية الله وعظمته وقدرته المطلقة على دفع أي ضرر.'),
        Dhikr(text: 'اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ', count: 3, reference: 'آية الكرسي - سورة البقرة (الآية 255)', description: 'فضلها: أعظم آية في كتاب الله، من قرأها لا يزال عليه من الله حافظ ولا يقربه شيطان.'),
        Dhikr(text: 'آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ * لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ', count: 1, reference: 'خواتيم سورة البقرة (الآيات 285-286)', description: 'فضلها: من قرأهما في ليلة كفتاه (أي كفتاه من كل شر وسوء).'),
        Dhikr(text: 'وَأَوْحَيْنَآ إِلَىَ مُوسَىَ أَنْ أَلْقِ عَصَاكَ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ * فَوَقَعَ الْحَقّ وَبَطَلَ مَا كَانُواْ يَعْمَلُونَ * فَغُلِبُواْ هُنَالِكَ وَانقَلَبُواْ صَاغِرِينَ * وَأُلْقِيَ السّحَرَةُ سَاجِدِينَ * قَالُوَاْ آمَنّا بِرَبّ الْعَالَمِينَ * رَبّ مُوسَىَ وَهَارُونَ', count: 7, reference: 'سورة الأعراف (الآيات 117-122) - آيات إبطال السحر', description: 'فضلها: آيات عظيمة لإبطال وفك السحر والعين القوية بإذن الله.'),
        Dhikr(text: 'وَقَالَ فِرْعَوْنُ ائْتُونِي بِكلّ سَاحِرٍ عَلِيمٍ * فَلَمّا جَآءَ السّحَرَةُ قَالَ لَهُمْ مّوسَىَ أَلْقُواْ مَآ أَنتُمْ مّلْقُونَ * فَلَمّآ أَلْقُواْ قَالَ مُوسَىَ مَا جِئْتُمْ بِهِ السّحْرُ إِنّ اللّهَ سَيُبْطِلُهُ إِنّ اللّهَ لاَ يُصْلِحُ عَمَلَ الْمُفْسِدِينَ * وَيُحِقّ اللّهُ الْحَقّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجِرِمُونَ', count: 7, reference: 'سورة يونس (الآيات 79-81) - آيات إبطال السحر', description: 'فضلها: إبطال مفعول السحر وكسر عقد السحرة وإحقاق الحق.'),
        Dhikr(text: 'قَالُواْ يَمُوسَىَ إِمّآ أَن تُلْقِيَ وَإِمّآ أَن نّكُونَ أَوّلَ مَنْ أَلْقَىَ * قَالَ بَلْ أَلْقُواْ فَإِذَا حِبَالُهُمْ وَعِصِيّهُمْ يُخَيّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنّهَا تَسْعَىَ * فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً مّوسَىَ * قُلْنَا لاَ تَخَفْ إِنّكَ أَنتَ الأعْلَىَ * وَأَلْقِ مَا فِي يَمِينِكَ تَلْقَفْ مَا صَنَعُواْ إِنّمَا صَنَعُواْ كَيْدُ سَاحِرٍ وَلاَ يُفْلِحُ السّاحِرُ حَيْثُ أَتَىَ', count: 7, reference: 'سورة طه (الآيات 65-69) - آيات إبطال السحر', description: 'فضلها: إبطال كيد الساحر وتثبيت القلب وطرد الخوف الذي تسببه الشياطين.'),
        Dhikr(text: 'قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ * لَمْ يَلِدْ وَلَمْ يُولَد * وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ', count: 3, reference: 'سورة الإخلاص', description: 'فضلها: تعدل ثلث القرآن، وفيها توحيد كامل يكفي المسلم من كل شر.'),
        Dhikr(text: 'قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ * مِن شَرِّ مَا خَلَقَ * وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ * وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ * وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ', count: 3, reference: 'سورة الفلق', description: 'فضلها: الاستعاذة بالله من شرور المخلوقات، ومن شر السواحر اللاتي ينفثن في العقد، ومن شر الحاسد.'),
        Dhikr(text: 'قُلْ أَعُوذُ بِرَبِّ النَّاسِ * مَلِكِ النَّاسِ * إِلَٰهِ النَّاسِ * مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ * الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ * مِنَ الْجِنَّةِ وَالنَّاسِ', count: 3, reference: 'سورة الناس', description: 'فضلها: الاستعاذة بالله من شياطين الإنس والجن، ودفع الوساوس.'),
        Dhikr(text: 'بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ', count: 3, reference: 'سنن أبي داود والترمذي / الدعاء النبوي', description: 'فضلها: من قالها صباحاً ومساءً لم يضره شيء طوال اليوم.'),
        Dhikr(text: 'أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ', count: 3, reference: 'صحيح مسلم / الدعاء النبوي', description: 'فضلها: من قالها لم يضره شيء حتى يرتحل من منزله، وهي وقاية من شرور كافة المخلوقات.'),
        Dhikr(text: 'حَسْبِيَ اللَّهُ لا إِلَـهَ إِلاَّ هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ', count: 7, reference: 'سنن أبي داود / الدعاء النبوي', description: 'فضلها: من قالها كفاه الله ما أهمه من أمر الدنيا والآخرة.'),
        Dhikr(text: 'أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ', count: 3, reference: 'صحيح البخاري / الدعاء النبوي', description: 'فضلها: تعويذ نبوي عظيم للتحصين من العين، الحاسدين، الشياطين، والهوام الضارة.'),
        Dhikr(text: 'بِسْمِ اللَّهِ، أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ', count: 3, reference: 'سنن أبي داود والترمذي / الدعاء النبوي', description: 'فضلها: دفع الفزع، والأرق، ووساوس الشياطين، وتحصين العبد من حضورهم وأذاهم.'),
        Dhikr(text: 'أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ الَّتِي لَا يُجَاوِزُهُنَّ بَرٌّ وَلَا فَاجِرٌ، مِنْ شَرِّ مَا خَلَقَ وَذَرَأَ وَبَرَأَ، وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ، وَمِنْ شَرِّ مَا يَعْرُجُ فِيهَا، وَمِنْ شَرِّ مَا ذَرَأَ فِي الْأَرْضِ، وَمِنْ شَرِّ مَا يَخْرُجُ مِنْهَا، وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ، وَمِنْ شَرِّ كُلِّ طَارِقٍ إِلَّا طَارِقًا يَطْرُقُ بِخَيْرٍ يَا رَحْمَنُ', count: 3, reference: 'مسند أحمد / الدعاء النبوي', description: 'فضلها: تحصين نبوي شديد الشبه لمنع كيد الشياطين ومردة الجن، ودفع شرور طوارق الليل والنهار وما ينزل من السماء وما يخرج من الأرض.'),
        Dhikr(text: 'بِسْمِ اللَّهِ', count: 3, reference: 'صحيح مسلم / الدعاء النبوي', description: 'فضلها: تقال قبل التعوذ بالله من الوجع والألم مع وضع اليد على موضع الألم.'),
        Dhikr(text: 'أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ', count: 7, reference: 'صحيح مسلم / الدعاء النبوي', description: 'فضلها: تقال بعد البسملة ثلاثاً مع وضع اليد على موضع الألم للشفاء منه.'),
        Dhikr(text: 'اللَّهُمَّ رَبَّ النَّاسِ أَذْهِبْ الْبَاسَ، اشْفِهِ وَأَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا', count: 7, reference: 'صحيح البخاري / رقية النبي', description: 'فضلها: دعاء النبي صلى الله عليه وسلم للشفاء التام من كل مرض أو أذى.'),
        Dhikr(text: 'بِسْمِ اللَّهِ يُبْرِيكَ، وَمِنْ كُلِّ دَاءٍ يَشْفِيكَ، وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ، وَشَرِّ كُلِّ ذِي عَيْنٍ', count: 3, reference: 'صحيح مسلم / رقية جبريل', description: 'فضلها: دعاء عظيم رقَى به جبريل عليه السلام النبي صلى الله عليه وسلم، للشفاء من كل داء وحسد.'),
